<script setup lang="ts">
import { ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { errorText } from '../api/http'
const auth=useAuthStore(),route=useRoute(),router=useRouter();const username=ref(''),password=ref(''),busy=ref(false),error=ref(String(route.query.reason||''))
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{await auth.login(username.value.trim(),password.value);const redirect=String(route.query.redirect||'/workbench');await router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')?redirect:'/workbench')}catch(e){error.value=errorText(e)}finally{password.value='';busy.value=false}}
</script>
<template><div class="login-page"><div class="login-brand"><span class="brand-mark">M</span><strong>轻量制造管理平台</strong></div><section class="login-intro"><span class="eyebrow">电脑组装工厂 · 制造工作空间</span><h1>从零部件采购，<br>到每一台整机交付。</h1><p>让采购、生产、仓储与销售在一个工作空间内有序衔接。</p><div class="login-process"><span>ERP 采购销售</span><span>MES 整机生产</span><span>WMS 库存追踪</span></div><p class="login-note">每笔业务可追踪 · 每次库存变动有据可查</p></section><section class="login-card"><div class="login-title"><h2>欢迎回来</h2><p class="muted">使用你的工作账号登录</p></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="username" placeholder="请输入账号" size="large" autocomplete="username" aria-label="账号" :maxlength="50"/></el-form-item><el-form-item label="密码"><el-input v-model="password" placeholder="请输入密码" type="password" show-password size="large" autocomplete="current-password" aria-label="密码"/></el-form-item><el-button type="primary" size="large" native-type="submit" :loading="busy" :disabled="!username||!password" class="login-submit">登录工作空间</el-button></el-form><p class="login-security">账号由管理员分配 · Cookie 安全会话</p></section><footer>轻量制造管理平台 · ERP / MES / WMS</footer></div></template>
